	port.CellsPush(pa, kind)
	port.CellsPush(pa, x0)
	port.CellsPush(pa, y0)
	port.CellsPush(pa, x1)
	port.CellsPush(pa, y1)
	port.CellsPush(pa, fill)
	port.CellsPush(pa, stroke)
	port.CellsPush(pa, 75)
	port.CellsPush(pa, 1000)
	port.CellsPush(pa, 1000)
